import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import ThoughtSpotShell from './components/ThoughtSpotShell';
import { TierProvider } from './config/TierContext';
import Sidebar, { SIDEBAR_WIDTH } from './components/NavHeader';
import LandingPage from './pages/LandingPage';
import Dashboard from './pages/Dashboard';
import Spotter from './pages/Spotter';
import Reports from './pages/Reports';
import Settings from './pages/Settings';
import './App.css';

function App() {
  return (
    <TierProvider>
      <ThoughtSpotShell>
        <Router>
          <div className="App" style={{ display: 'flex', minHeight: '100vh' }}>
            <Sidebar />
            <main style={{ marginLeft: SIDEBAR_WIDTH, flex: 1, minHeight: '100vh' }}>
              <Routes>
                <Route path="/" element={<LandingPage />} />
                <Route path="/dashboard" element={<Dashboard />} />
                <Route path="/spotter" element={<Spotter />} />
                <Route path="/reports" element={<Reports />} />
                <Route path="/settings" element={<Settings />} />
              </Routes>
            </main>
          </div>
        </Router>
      </ThoughtSpotShell>
    </TierProvider>
  );
}

export default App;
